CREATE TABLE IF NOT EXISTS saliyah_sim_properties (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,kind TEXT NOT NULL,location TEXT NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL,sold_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS saliyah_sim_property_trades (id TEXT PRIMARY KEY,property_id TEXT NOT NULL,seller_id TEXT NOT NULL,buyer_id TEXT NOT NULL,price INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS saliyah_sim_shares (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,owner_id TEXT NOT NULL,units INTEGER NOT NULL CHECK(units>=0));
CREATE TABLE IF NOT EXISTS saliyah_sim_share_trades (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,seller_id TEXT NOT NULL,buyer_id TEXT NOT NULL,units INTEGER NOT NULL,price_per_unit INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS saliyah_sim_marriages (id TEXT PRIMARY KEY,partner_a TEXT NOT NULL,partner_b TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS saliyah_sim_life_events (id TEXT PRIMARY KEY,citizen_id TEXT NOT NULL,kind TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);